package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"
)

// agentSessionJSON mirrors the external protocol's AgentSessionJSON type.
type agentSessionJSON struct {
	SessionID     string   `json:"session_id"`
	AgentName     string   `json:"agent_name"`
	RepoPath      string   `json:"repo_path"`
	SessionRef    string   `json:"session_ref"`
	StartTime     string   `json:"start_time"`
	NativeData    []byte   `json:"native_data"`
	ModifiedFiles []string `json:"modified_files"`
	NewFiles      []string `json:"new_files"`
	DeletedFiles  []string `json:"deleted_files"`
}

// hookInputJSON mirrors the external protocol's HookInputJSON type.
type hookInputJSON struct {
	HookType   string                 `json:"hook_type"`
	SessionID  string                 `json:"session_id"`
	SessionRef string                 `json:"session_ref"`
	Timestamp  string                 `json:"timestamp"`
	UserPrompt string                 `json:"user_prompt,omitempty"`
	ToolName   string                 `json:"tool_name,omitempty"`
	ToolUseID  string                 `json:"tool_use_id,omitempty"`
	ToolInput  json.RawMessage        `json:"tool_input,omitempty"`
	RawData    map[string]interface{} `json:"raw_data,omitempty"`
}

var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)

func sanitizePathForCursor(path string) string {
	path = strings.TrimLeft(path, "/")
	return nonAlphanumericRegex.ReplaceAllString(path, "-")
}

// cmdDetect checks if .cursor/ directory exists in the repo root.
func cmdDetect() error {
	repoRoot := os.Getenv("ENTIRE_REPO_ROOT")
	if repoRoot == "" {
		repoRoot = "."
	}

	cursorDir := filepath.Join(repoRoot, ".cursor")
	_, err := os.Stat(cursorDir)
	present := err == nil

	return writeJSON(map[string]bool{"present": present})
}

// cmdGetSessionID extracts session_id from the HookInputJSON on stdin.
func cmdGetSessionID() error {
	var input hookInputJSON
	if err := json.NewDecoder(os.Stdin).Decode(&input); err != nil {
		return fmt.Errorf("failed to parse hook input: %w", err)
	}
	return writeJSON(map[string]string{"session_id": input.SessionID})
}

// cmdGetSessionDir returns the cursor transcript directory for the given repo.
func cmdGetSessionDir(repoPath string) error {
	if override := os.Getenv("ENTIRE_TEST_CURSOR_PROJECT_DIR"); override != "" {
		return writeJSON(map[string]string{"session_dir": override})
	}

	homeDir, err := os.UserHomeDir()
	if err != nil {
		return fmt.Errorf("failed to get home directory: %w", err)
	}

	projectDir := sanitizePathForCursor(repoPath)
	sessionDir := filepath.Join(homeDir, ".cursor", "projects", projectDir, "agent-transcripts")
	return writeJSON(map[string]string{"session_dir": sessionDir})
}

// cmdResolveSessionFile returns the path to the session file.
// Cursor IDE uses nested: <dir>/<id>/<id>.jsonl
// Cursor CLI uses flat: <dir>/<id>.jsonl
func cmdResolveSessionFile(sessionDir, sessionID string) error {
	nestedDir := filepath.Join(sessionDir, sessionID)
	nested := filepath.Join(nestedDir, sessionID+".jsonl")
	if _, err := os.Stat(nested); err == nil {
		return writeJSON(map[string]string{"session_file": nested})
	}
	// IDE creates the directory before the transcript file
	if info, err := os.Stat(nestedDir); err == nil && info.IsDir() {
		return writeJSON(map[string]string{"session_file": nested})
	}
	flat := filepath.Join(sessionDir, sessionID+".jsonl")
	return writeJSON(map[string]string{"session_file": flat})
}

// cmdReadSession reads a session from Cursor's JSONL transcript file.
func cmdReadSession() error {
	var input hookInputJSON
	if err := json.NewDecoder(os.Stdin).Decode(&input); err != nil {
		return fmt.Errorf("failed to parse hook input: %w", err)
	}

	if input.SessionRef == "" {
		return errors.New("session reference (transcript path) is required")
	}

	data, err := os.ReadFile(input.SessionRef) //nolint:gosec // Path from protocol input
	if err != nil {
		return fmt.Errorf("failed to read transcript: %w", err)
	}

	session := agentSessionJSON{
		SessionID:  input.SessionID,
		AgentName:  "cursor",
		SessionRef: input.SessionRef,
		StartTime:  time.Now().Format(time.RFC3339),
		NativeData: data,
	}
	return writeJSON(session)
}

// cmdWriteSession writes native data to the session ref path.
func cmdWriteSession() error {
	var session agentSessionJSON
	if err := json.NewDecoder(os.Stdin).Decode(&session); err != nil {
		return fmt.Errorf("failed to parse session: %w", err)
	}

	if session.SessionRef == "" {
		return errors.New("session reference (transcript path) is required")
	}

	if len(session.NativeData) == 0 {
		return errors.New("session has no native data to write")
	}

	if session.AgentName != "" && session.AgentName != "cursor" {
		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, "cursor")
	}

	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
		return fmt.Errorf("failed to write transcript: %w", err)
	}

	return nil
}

// cmdFormatResumeCommand returns an instruction to resume a Cursor session.
func cmdFormatResumeCommand() error {
	return writeJSON(map[string]string{
		"command": "Open this project in Cursor to continue the session.",
	})
}

// cmdReadTranscript reads raw transcript bytes from the session ref.
func cmdReadTranscript(sessionRef string) error {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path from protocol input
	if err != nil {
		return fmt.Errorf("failed to read transcript: %w", err)
	}
	_, err = os.Stdout.Write(data)
	return err
}

package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
)

const hooksFileName = "hooks.json"

// entireHookPrefixes are command prefixes that identify Entire hooks.
var entireHookPrefixes = []string{
	"entire ",
	"go run ${CURSOR_PROJECT_DIR}/cmd/entire/main.go ",
}

// Hook name constants.
const (
	hookNameSessionStart       = "session-start"
	hookNameSessionEnd         = "session-end"
	hookNameBeforeSubmitPrompt = "before-submit-prompt"
	hookNameStop               = "stop"
	hookNamePreCompact         = "pre-compact"
	hookNameSubagentStart      = "subagent-start"
	hookNameSubagentStop       = "subagent-stop"
)

// cmdInstallHooks installs Cursor hooks in .cursor/hooks.json.
func cmdInstallHooks(localDev, force bool) error {
	repoRoot := os.Getenv("ENTIRE_REPO_ROOT")
	if repoRoot == "" {
		repoRoot = "."
	}

	hooksPath := filepath.Join(repoRoot, ".cursor", hooksFileName)

	var rawFile map[string]json.RawMessage
	var rawHooks map[string]json.RawMessage

	existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path from repo root
	if readErr == nil {
		if err := json.Unmarshal(existingData, &rawFile); err != nil {
			return fmt.Errorf("failed to parse existing %s: %w", hooksFileName, err)
		}
		if hooksRaw, ok := rawFile["hooks"]; ok {
			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
				return fmt.Errorf("failed to parse hooks in %s: %w", hooksFileName, err)
			}
		}
		if _, ok := rawFile["version"]; !ok {
			rawFile["version"] = json.RawMessage(`1`)
		}
	} else {
		rawFile = map[string]json.RawMessage{
			"version": json.RawMessage(`1`),
		}
	}

	if rawHooks == nil {
		rawHooks = make(map[string]json.RawMessage)
	}

	var sessionStart, sessionEnd, beforeSubmitPrompt, stop, preCompact, subagentStart, subagentStop []CursorHookEntry
	parseCursorHookType(rawHooks, "sessionStart", &sessionStart)
	parseCursorHookType(rawHooks, "sessionEnd", &sessionEnd)
	parseCursorHookType(rawHooks, "beforeSubmitPrompt", &beforeSubmitPrompt)
	parseCursorHookType(rawHooks, "stop", &stop)
	parseCursorHookType(rawHooks, "preCompact", &preCompact)
	parseCursorHookType(rawHooks, "subagentStart", &subagentStart)
	parseCursorHookType(rawHooks, "subagentStop", &subagentStop)

	if force {
		sessionStart = removeEntireHooks(sessionStart)
		sessionEnd = removeEntireHooks(sessionEnd)
		beforeSubmitPrompt = removeEntireHooks(beforeSubmitPrompt)
		stop = removeEntireHooks(stop)
		preCompact = removeEntireHooks(preCompact)
		subagentStart = removeEntireHooks(subagentStart)
		subagentStop = removeEntireHooks(subagentStop)
	}

	var cmdPrefix string
	if localDev {
		cmdPrefix = "go run ${CURSOR_PROJECT_DIR}/cmd/entire/main.go hooks cursor "
	} else {
		cmdPrefix = "entire hooks cursor "
	}

	cmds := map[string]*[]CursorHookEntry{
		cmdPrefix + hookNameSessionStart:       &sessionStart,
		cmdPrefix + hookNameSessionEnd:         &sessionEnd,
		cmdPrefix + hookNameBeforeSubmitPrompt: &beforeSubmitPrompt,
		cmdPrefix + hookNameStop:               &stop,
		cmdPrefix + hookNamePreCompact:         &preCompact,
		cmdPrefix + hookNameSubagentStart:      &subagentStart,
		cmdPrefix + hookNameSubagentStop:       &subagentStop,
	}

	count := 0
	for cmd, entries := range cmds {
		if !hookCommandExists(*entries, cmd) {
			*entries = append(*entries, CursorHookEntry{Command: cmd})
			count++
		}
	}

	if count == 0 {
		return writeJSON(map[string]int{"hooks_installed": 0})
	}

	marshalCursorHookType(rawHooks, "sessionStart", sessionStart)
	marshalCursorHookType(rawHooks, "sessionEnd", sessionEnd)
	marshalCursorHookType(rawHooks, "beforeSubmitPrompt", beforeSubmitPrompt)
	marshalCursorHookType(rawHooks, "stop", stop)
	marshalCursorHookType(rawHooks, "preCompact", preCompact)
	marshalCursorHookType(rawHooks, "subagentStart", subagentStart)
	marshalCursorHookType(rawHooks, "subagentStop", subagentStop)

	hooksJSON, err := json.Marshal(rawHooks)
	if err != nil {
		return fmt.Errorf("failed to marshal hooks: %w", err)
	}
	rawFile["hooks"] = hooksJSON

	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
		return fmt.Errorf("failed to create .cursor directory: %w", err)
	}

	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal %s: %w", hooksFileName, err)
	}

	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
		return fmt.Errorf("failed to write %s: %w", hooksFileName, err)
	}

	return writeJSON(map[string]int{"hooks_installed": count})
}

// cmdUninstallHooks removes Entire hooks from .cursor/hooks.json.
func cmdUninstallHooks() error {
	repoRoot := os.Getenv("ENTIRE_REPO_ROOT")
	if repoRoot == "" {
		repoRoot = "."
	}

	hooksPath := filepath.Join(repoRoot, ".cursor", hooksFileName)
	data, err := os.ReadFile(hooksPath) //nolint:gosec // path from repo root
	if err != nil {
		return nil // No hooks file means nothing to uninstall
	}

	var rawFile map[string]json.RawMessage
	if err := json.Unmarshal(data, &rawFile); err != nil {
		return fmt.Errorf("failed to parse %s: %w", hooksFileName, err)
	}

	var rawHooks map[string]json.RawMessage
	if hooksRaw, ok := rawFile["hooks"]; ok {
		if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
			return fmt.Errorf("failed to parse hooks in %s: %w", hooksFileName, err)
		}
	}
	if rawHooks == nil {
		rawHooks = make(map[string]json.RawMessage)
	}

	var sessionStart, sessionEnd, beforeSubmitPrompt, stop, preCompact, subagentStart, subagentStop []CursorHookEntry
	parseCursorHookType(rawHooks, "sessionStart", &sessionStart)
	parseCursorHookType(rawHooks, "sessionEnd", &sessionEnd)
	parseCursorHookType(rawHooks, "beforeSubmitPrompt", &beforeSubmitPrompt)
	parseCursorHookType(rawHooks, "stop", &stop)
	parseCursorHookType(rawHooks, "preCompact", &preCompact)
	parseCursorHookType(rawHooks, "subagentStart", &subagentStart)
	parseCursorHookType(rawHooks, "subagentStop", &subagentStop)

	sessionStart = removeEntireHooks(sessionStart)
	sessionEnd = removeEntireHooks(sessionEnd)
	beforeSubmitPrompt = removeEntireHooks(beforeSubmitPrompt)
	stop = removeEntireHooks(stop)
	preCompact = removeEntireHooks(preCompact)
	subagentStart = removeEntireHooks(subagentStart)
	subagentStop = removeEntireHooks(subagentStop)

	marshalCursorHookType(rawHooks, "sessionStart", sessionStart)
	marshalCursorHookType(rawHooks, "sessionEnd", sessionEnd)
	marshalCursorHookType(rawHooks, "beforeSubmitPrompt", beforeSubmitPrompt)
	marshalCursorHookType(rawHooks, "stop", stop)
	marshalCursorHookType(rawHooks, "preCompact", preCompact)
	marshalCursorHookType(rawHooks, "subagentStart", subagentStart)
	marshalCursorHookType(rawHooks, "subagentStop", subagentStop)

	if len(rawHooks) > 0 {
		hooksJSON, err := json.Marshal(rawHooks)
		if err != nil {
			return fmt.Errorf("failed to marshal hooks: %w", err)
		}
		rawFile["hooks"] = hooksJSON
	} else {
		delete(rawFile, "hooks")
	}

	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal %s: %w", hooksFileName, err)
	}

	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
		return fmt.Errorf("failed to write %s: %w", hooksFileName, err)
	}
	return nil
}

// cmdAreHooksInstalled checks if Entire hooks are installed.
func cmdAreHooksInstalled() error {
	repoRoot := os.Getenv("ENTIRE_REPO_ROOT")
	if repoRoot == "" {
		repoRoot = "."
	}

	hooksPath := filepath.Join(repoRoot, ".cursor", hooksFileName)
	data, err := os.ReadFile(hooksPath) //nolint:gosec // path from repo root
	if err != nil {
		return writeJSON(map[string]bool{"installed": false})
	}

	var hooksFile CursorHooksFile
	if err := json.Unmarshal(data, &hooksFile); err != nil {
		return writeJSON(map[string]bool{"installed": false})
	}

	installed := hasEntireHook(hooksFile.Hooks.SessionStart) ||
		hasEntireHook(hooksFile.Hooks.SessionEnd) ||
		hasEntireHook(hooksFile.Hooks.BeforeSubmitPrompt) ||
		hasEntireHook(hooksFile.Hooks.Stop) ||
		hasEntireHook(hooksFile.Hooks.PreCompact) ||
		hasEntireHook(hooksFile.Hooks.SubagentStart) ||
		hasEntireHook(hooksFile.Hooks.SubagentStop)

	return writeJSON(map[string]bool{"installed": installed})
}

// parseCursorHookType parses a specific hook type from rawHooks into the target slice.
func parseCursorHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]CursorHookEntry) {
	if data, ok := rawHooks[hookType]; ok {
		//nolint:errcheck,gosec // Intentionally ignoring parse errors
		json.Unmarshal(data, target)
	}
}

// marshalCursorHookType marshals a hook type back into rawHooks.
func marshalCursorHookType(rawHooks map[string]json.RawMessage, hookType string, entries []CursorHookEntry) {
	if len(entries) == 0 {
		delete(rawHooks, hookType)
		return
	}
	data, err := json.Marshal(entries)
	if err != nil {
		return
	}
	rawHooks[hookType] = data
}

func hookCommandExists(entries []CursorHookEntry, command string) bool {
	for _, entry := range entries {
		if entry.Command == command {
			return true
		}
	}
	return false
}

func isEntireHook(command string) bool {
	for _, prefix := range entireHookPrefixes {
		if strings.HasPrefix(command, prefix) {
			return true
		}
	}
	return false
}

func hasEntireHook(entries []CursorHookEntry) bool {
	for _, entry := range entries {
		if isEntireHook(entry.Command) {
			return true
		}
	}
	return false
}

func removeEntireHooks(entries []CursorHookEntry) []CursorHookEntry {
	result := make([]CursorHookEntry, 0, len(entries))
	for _, entry := range entries {
		if !isEntireHook(entry.Command) {
			result = append(result, entry)
		}
	}
	return result
}

package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"time"
)

// Event type constants matching agent.EventType iota values.
const (
	eventSessionStart = 1
	eventTurnStart    = 2
	eventTurnEnd      = 3
	eventCompaction   = 4
	eventSessionEnd   = 5
	eventSubagentStart = 6
	eventSubagentEnd  = 7
)

// eventJSON is the protocol's event representation.
type eventJSON struct {
	Type              int               `json:"type"`
	SessionID         string            `json:"session_id"`
	PreviousSessionID string            `json:"previous_session_id,omitempty"`
	SessionRef        string            `json:"session_ref,omitempty"`
	Prompt            string            `json:"prompt,omitempty"`
	Model             string            `json:"model,omitempty"`
	Timestamp         string            `json:"timestamp,omitempty"`
	ToolUseID         string            `json:"tool_use_id,omitempty"`
	SubagentID        string            `json:"subagent_id,omitempty"`
	ToolInput         json.RawMessage   `json:"tool_input,omitempty"`
	SubagentType      string            `json:"subagent_type,omitempty"`
	TaskDescription   string            `json:"task_description,omitempty"`
	ResponseMessage   string            `json:"response_message,omitempty"`
	Metadata          map[string]string `json:"metadata,omitempty"`
}

// cmdParseHook dispatches to the appropriate hook parser.
func cmdParseHook(hookName string) error {
	switch hookName {
	case hookNameSessionStart:
		return parseSessionStart(os.Stdin)
	case hookNameBeforeSubmitPrompt:
		return parseTurnStart(os.Stdin)
	case hookNameStop:
		return parseTurnEnd(os.Stdin)
	case hookNameSessionEnd:
		return parseSessionEnd(os.Stdin)
	case hookNamePreCompact:
		return parsePreCompact(os.Stdin)
	case hookNameSubagentStart:
		return parseSubagentStart(os.Stdin)
	case hookNameSubagentStop:
		return parseSubagentStop(os.Stdin)
	default:
		return writeNull()
	}
}

// resolveTranscriptRef returns the transcript path, or computes it dynamically
// when the hook doesn't provide one (Cursor CLI pattern).
func resolveTranscriptRef(conversationID, rawPath string) string {
	if rawPath != "" {
		return rawPath
	}

	repoRoot := os.Getenv("ENTIRE_REPO_ROOT")
	if repoRoot == "" {
		return ""
	}

	sessionDir, err := getSessionDir(repoRoot)
	if err != nil {
		return ""
	}

	return resolveSessionFile(sessionDir, conversationID)
}

// getSessionDir computes the session directory for a repo path.
func getSessionDir(repoPath string) (string, error) {
	if override := os.Getenv("ENTIRE_TEST_CURSOR_PROJECT_DIR"); override != "" {
		return override, nil
	}

	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("failed to get home directory: %w", err)
	}

	projectDir := sanitizePathForCursor(repoPath)
	return filepath.Join(homeDir, ".cursor", "projects", projectDir, "agent-transcripts"), nil
}

// resolveSessionFile returns the resolved session file path.
func resolveSessionFile(sessionDir, sessionID string) string {
	nestedDir := filepath.Join(sessionDir, sessionID)
	nested := filepath.Join(nestedDir, sessionID+".jsonl")
	if _, err := os.Stat(nested); err == nil {
		return nested
	}
	if info, err := os.Stat(nestedDir); err == nil && info.IsDir() {
		return nested
	}
	return filepath.Join(sessionDir, sessionID+".jsonl")
}

func readAndParse[T any](stdin io.Reader) (*T, error) {
	data, err := io.ReadAll(stdin)
	if err != nil {
		return nil, fmt.Errorf("failed to read hook input: %w", err)
	}
	if len(data) == 0 {
		return nil, errors.New("empty hook input")
	}
	var result T
	if err := json.Unmarshal(data, &result); err != nil {
		return nil, fmt.Errorf("failed to parse hook input: %w", err)
	}
	return &result, nil
}

func nowRFC3339() string {
	return time.Now().Format(time.RFC3339)
}

func parseSessionStart(stdin io.Reader) error {
	raw, err := readAndParse[sessionStartRaw](stdin)
	if err != nil {
		return err
	}
	return writeJSON(eventJSON{
		Type:       eventSessionStart,
		SessionID:  raw.ConversationID,
		SessionRef: raw.TranscriptPath,
		Timestamp:  nowRFC3339(),
	})
}

func parseTurnStart(stdin io.Reader) error {
	raw, err := readAndParse[beforeSubmitPromptInputRaw](stdin)
	if err != nil {
		return err
	}
	return writeJSON(eventJSON{
		Type:       eventTurnStart,
		SessionID:  raw.ConversationID,
		SessionRef: resolveTranscriptRef(raw.ConversationID, raw.TranscriptPath),
		Prompt:     raw.Prompt,
		Model:      raw.Model,
		Timestamp:  nowRFC3339(),
	})
}

func parseTurnEnd(stdin io.Reader) error {
	raw, err := readAndParse[stopHookInputRaw](stdin)
	if err != nil {
		return err
	}
	return writeJSON(eventJSON{
		Type:       eventTurnEnd,
		SessionID:  raw.ConversationID,
		SessionRef: resolveTranscriptRef(raw.ConversationID, raw.TranscriptPath),
		Model:      raw.Model,
		Timestamp:  nowRFC3339(),
	})
}

func parseSessionEnd(stdin io.Reader) error {
	raw, err := readAndParse[sessionEndRaw](stdin)
	if err != nil {
		return err
	}
	return writeJSON(eventJSON{
		Type:       eventSessionEnd,
		SessionID:  raw.ConversationID,
		SessionRef: resolveTranscriptRef(raw.ConversationID, raw.TranscriptPath),
		Timestamp:  nowRFC3339(),
	})
}

func parsePreCompact(stdin io.Reader) error {
	raw, err := readAndParse[preCompactHookInputRaw](stdin)
	if err != nil {
		return err
	}
	return writeJSON(eventJSON{
		Type:       eventCompaction,
		SessionID:  raw.ConversationID,
		SessionRef: raw.TranscriptPath,
		Timestamp:  nowRFC3339(),
	})
}

func parseSubagentStart(stdin io.Reader) error {
	raw, err := readAndParse[subagentStartHookInputRaw](stdin)
	if err != nil {
		return err
	}
	if raw.Task == "" {
		return writeNull()
	}
	return writeJSON(eventJSON{
		Type:            eventSubagentStart,
		SessionID:       raw.ConversationID,
		SessionRef:      raw.TranscriptPath,
		SubagentID:      raw.SubagentID,
		ToolUseID:       raw.SubagentID,
		SubagentType:    raw.SubagentType,
		TaskDescription: raw.Task,
		Timestamp:       nowRFC3339(),
	})
}

func parseSubagentStop(stdin io.Reader) error {
	raw, err := readAndParse[subagentStopHookInputRaw](stdin)
	if err != nil {
		return err
	}
	if raw.Task == "" {
		return writeNull()
	}
	return writeJSON(eventJSON{
		Type:            eventSubagentEnd,
		SessionID:       raw.ConversationID,
		SessionRef:      raw.TranscriptPath,
		ToolUseID:       raw.SubagentID,
		SubagentID:      raw.SubagentID,
		SubagentType:    raw.SubagentType,
		TaskDescription: raw.Task,
		Timestamp:       nowRFC3339(),
	})
}

package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"os"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/textutil"
	"github.com/entireio/cli/cmd/entire/cli/transcript"
)

// cmdChunkTranscript splits JSONL content from stdin at line boundaries.
func cmdChunkTranscript(maxSize int) error {
	data, err := io.ReadAll(os.Stdin)
	if err != nil {
		return fmt.Errorf("failed to read stdin: %w", err)
	}

	chunks, err := agent.ChunkJSONL(data, maxSize)
	if err != nil {
		return fmt.Errorf("failed to chunk JSONL transcript: %w", err)
	}

	return writeJSON(struct {
		Chunks [][]byte `json:"chunks"`
	}{Chunks: chunks})
}

// cmdReassembleTranscript concatenates JSONL chunks from stdin.
func cmdReassembleTranscript() error {
	var input struct {
		Chunks [][]byte `json:"chunks"`
	}
	if err := json.NewDecoder(os.Stdin).Decode(&input); err != nil {
		return fmt.Errorf("failed to parse stdin: %w", err)
	}

	result := agent.ReassembleJSONL(input.Chunks)
	_, err := os.Stdout.Write(result)
	return err
}

// cmdGetTranscriptPosition returns the line count of the transcript file.
func cmdGetTranscriptPosition(path string) error {
	if path == "" {
		return writeJSON(map[string]int{"position": 0})
	}

	file, err := os.Open(path) //nolint:gosec // Path from protocol input
	if err != nil {
		if os.IsNotExist(err) {
			return writeJSON(map[string]int{"position": 0})
		}
		return fmt.Errorf("failed to open transcript file: %w", err)
	}
	defer file.Close()

	reader := bufio.NewReader(file)
	lineCount := 0

	for {
		line, readErr := reader.ReadBytes('\n')
		if readErr != nil {
			if readErr == io.EOF {
				if len(line) > 0 {
					lineCount++
				}
				break
			}
			return fmt.Errorf("failed to read transcript: %w", readErr)
		}
		lineCount++
	}

	return writeJSON(map[string]int{"position": lineCount})
}

// cmdExtractModifiedFiles always returns empty since Cursor transcripts
// do not contain tool_use blocks for file detection.
func cmdExtractModifiedFiles() error {
	return writeJSON(struct {
		Files           []string `json:"files"`
		CurrentPosition int      `json:"current_position"`
	}{
		Files:           nil,
		CurrentPosition: 0,
	})
}

// cmdExtractPrompts extracts user prompts from the transcript.
func cmdExtractPrompts(sessionRef string, fromOffset int) error {
	lines, err := transcript.ParseFromFileAtLine(sessionRef, fromOffset)
	if err != nil {
		return fmt.Errorf("failed to parse transcript: %w", err)
	}

	var prompts []string
	for i := range lines {
		if lines[i].Type != transcript.TypeUser {
			continue
		}
		content := transcript.ExtractUserContent(lines[i].Message)
		if content != "" {
			prompts = append(prompts, textutil.StripIDEContextTags(content))
		}
	}

	return writeJSON(struct {
		Prompts []string `json:"prompts"`
	}{Prompts: prompts})
}

// cmdExtractSummary extracts the last assistant text block as a summary.
func cmdExtractSummary(sessionRef string) error {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path from protocol input
	if err != nil {
		return fmt.Errorf("failed to read transcript: %w", err)
	}

	lines, parseErr := transcript.ParseFromBytes(data)
	if parseErr != nil {
		return fmt.Errorf("failed to parse transcript: %w", parseErr)
	}

	for i := len(lines) - 1; i >= 0; i-- {
		if lines[i].Type != transcript.TypeAssistant {
			continue
		}
		var msg transcript.AssistantMessage
		if err := json.Unmarshal(lines[i].Message, &msg); err != nil {
			continue
		}
		for _, block := range msg.Content {
			if block.Type == transcript.ContentTypeText && block.Text != "" {
				return writeJSON(struct {
					Summary    string `json:"summary"`
					HasSummary bool   `json:"has_summary"`
				}{Summary: block.Text, HasSummary: true})
			}
		}
	}

	return writeJSON(struct {
		Summary    string `json:"summary"`
		HasSummary bool   `json:"has_summary"`
	}{Summary: "", HasSummary: false})
}

// Binary entire-agent-cursor implements the external agent protocol for the Cursor IDE.
// It is discovered via PATH by the CLI's external.DiscoverAndRegister().
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"strconv"
)

func main() {
	if len(os.Args) < 2 {
		fatal("usage: entire-agent-cursor <subcommand> [args...]")
	}

	var err error
	switch os.Args[1] {
	case "info":
		err = cmdInfo()
	case "detect":
		err = cmdDetect()
	case "get-session-id":
		err = cmdGetSessionID()
	case "get-session-dir":
		err = runGetSessionDir()
	case "resolve-session-file":
		err = runResolveSessionFile()
	case "read-session":
		err = cmdReadSession()
	case "write-session":
		err = cmdWriteSession()
	case "format-resume-command":
		err = cmdFormatResumeCommand()
	case "read-transcript":
		err = runReadTranscript()
	case "chunk-transcript":
		err = runChunkTranscript()
	case "reassemble-transcript":
		err = cmdReassembleTranscript()
	case "parse-hook":
		err = runParseHook()
	case "install-hooks":
		err = runInstallHooks()
	case "uninstall-hooks":
		err = cmdUninstallHooks()
	case "are-hooks-installed":
		err = cmdAreHooksInstalled()
	case "get-transcript-position":
		err = runGetTranscriptPosition()
	case "extract-modified-files":
		err = cmdExtractModifiedFiles()
	case "extract-prompts":
		err = runExtractPrompts()
	case "extract-summary":
		err = runExtractSummary()
	default:
		fatal("unknown subcommand: " + os.Args[1])
	}

	if err != nil {
		fatal(err.Error())
	}
}

func cmdInfo() error {
	return writeJSON(map[string]interface{}{
		"protocol_version": 1,
		"name":             "cursor",
		"type":             "Cursor",
		"description":      "Cursor - AI-powered code editor",
		"is_preview":       true,
		"protected_dirs":   []string{".cursor"},
		"hook_names": []string{
			hookNameSessionStart,
			hookNameSessionEnd,
			hookNameBeforeSubmitPrompt,
			hookNameStop,
			hookNamePreCompact,
			hookNameSubagentStart,
			hookNameSubagentStop,
		},
		"capabilities": map[string]bool{
			"hooks":                    true,
			"transcript_analyzer":      true,
			"transcript_preparer":      false,
			"token_calculator":         false,
			"text_generator":           false,
			"hook_response_writer":     false,
			"subagent_aware_extractor": false,
		},
	})
}

func runGetSessionDir() error {
	fs := flag.NewFlagSet("get-session-dir", flag.ContinueOnError)
	repoPath := fs.String("repo-path", "", "repository path")
	if err := fs.Parse(os.Args[2:]); err != nil {
		return err
	}
	return cmdGetSessionDir(*repoPath)
}

func runResolveSessionFile() error {
	fs := flag.NewFlagSet("resolve-session-file", flag.ContinueOnError)
	sessionDir := fs.String("session-dir", "", "session directory")
	sessionID := fs.String("session-id", "", "session ID")
	if err := fs.Parse(os.Args[2:]); err != nil {
		return err
	}
	return cmdResolveSessionFile(*sessionDir, *sessionID)
